import re
import json

file_path = 'src/data/kpsea-science-2023.js'
with open(file_path, 'r', encoding='utf-8') as f:
    content = f.read()

def replacer(match):
    q_num_str = match.group(2)
    q_num = int(q_num_str)
    prefix = match.group(1)
    
    if q_num in explanations:
        new_exp = json.dumps(explanations[q_num])
        return prefix + new_exp
    return match.group(0)

# The regex matches questionNumber, then options, then explanation
pattern = re.compile(r'("questionNumber"\s*:\s*(\d+)\s*,[\s\S]*?"explanation"\s*:\s*)(["\'].*?(?<!\\)["\'])', re.DOTALL)

new_content = pattern.sub(replacer, content)

with open(file_path, 'w', encoding='utf-8') as f:
    f.write(new_content)

print("Updated Q1-Q25 in Science successfully.")
